* { box-sizing: border-box; margin: 0; }
body { font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif; background: #f0f2f5; color: #1f2937; }

.layout { display: flex; min-height: 100vh; }
.sidebar { width: 200px; background: #0f2a43; color: #cbd5e1; padding: 20px 0; flex-shrink: 0; }
.logo { font-size: 17px; font-weight: 700; color: #fff; padding: 0 20px 20px; border-bottom: 1px solid #1e3a5c; }
.sidebar nav { display: flex; flex-direction: column; margin-top: 12px; }
.sidebar a { color: #cbd5e1; text-decoration: none; padding: 12px 20px; font-size: 14px; }
.sidebar a:hover { background: #1e3a5c; }
.sidebar a.active { background: #2563eb; color: #fff; }
.content { flex: 1; padding: 24px 32px; overflow-x: auto; }

h2 { margin-bottom: 16px; font-size: 20px; }
h3 { margin: 20px 0 10px; font-size: 16px; }
.muted { color: #6b7280; font-size: 13px; }
.mono { font-family: ui-monospace, monospace; font-weight: 600; }
.msg { margin: 8px 0; font-size: 14px; }

.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; }
.card { background: #fff; border-radius: 10px; padding: 18px; box-shadow: 0 1px 3px rgba(0,0,0,.08); border-left: 4px solid #94a3b8; }
.card.blue { border-color: #2563eb; } .card.red { border-color: #dc2626; }
.card.orange { border-color: #ea580c; } .card.green { border-color: #16a34a; }
.card-value { font-size: 26px; font-weight: 700; }
.card.red .card-value { color: #dc2626; }
.card-label { color: #6b7280; font-size: 13px; margin-top: 4px; }

.panel { background: #fff; border-radius: 10px; padding: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.08); margin-bottom: 14px; }
.form-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
input, select { padding: 8px 10px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; }
button { padding: 8px 16px; background: #2563eb; color: #fff; border: none; border-radius: 6px; cursor: pointer; font-size: 14px; }
button:hover { background: #1d4ed8; }
.btn-sm { padding: 4px 10px; font-size: 12px; background: #475569; }
.btn-sm:hover { background: #334155; }
.toolbar { display: flex; gap: 10px; margin-bottom: 12px; }

table { width: 100%; border-collapse: collapse; background: #fff; border-radius: 10px; overflow: hidden; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
th, td { padding: 10px 12px; text-align: left; font-size: 13px; border-bottom: 1px solid #e5e7eb; }
th { background: #f8fafc; font-weight: 600; color: #475569; }
.row-red { background: #fef2f2; }

.tag { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 12px; margin-right: 4px; }
.s-BOOKED { background: #fef3c7; color: #92400e; }
.s-IN_YARD { background: #dbeafe; color: #1e40af; }
.s-OUT { background: #e5e7eb; color: #4b5563; }
.s-over { background: #fee2e2; color: #b91c1c; }
.v-SCHEDULED { background: #fef3c7; color: #92400e; }
.v-BERTHED { background: #dcfce7; color: #166534; }
.v-DEPARTED { background: #e5e7eb; color: #4b5563; }
.a-PENDING { background: #fef3c7; color: #92400e; }
.a-COMPLETED { background: #dcfce7; color: #166534; }
.a-CANCELLED { background: #e5e7eb; color: #4b5563; }

.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.two-col .panel { display: flex; flex-direction: column; gap: 10px; }

.summary-bar { display: flex; gap: 10px; margin-bottom: 12px; }
.block-btn { background: #fff; color: #1f2937; border: 1px solid #d1d5db; }
.block-btn.active { background: #2563eb; color: #fff; border-color: #2563eb; }
.legend { display: flex; align-items: center; gap: 6px; font-size: 13px; color: #6b7280; margin-bottom: 10px; }
.legend .cell { display: inline-block; width: 16px; height: 16px; }

.yard-grid { display: flex; gap: 16px; flex-wrap: wrap; }
.bay { background: #fff; border-radius: 8px; padding: 10px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
.bay-title { font-size: 12px; color: #6b7280; margin-bottom: 6px; text-align: center; }
.bay-cells { display: grid; grid-template-columns: repeat(4, 44px); gap: 4px; }
.cell { width: 44px; height: 28px; border-radius: 4px; font-size: 10px; display: flex; align-items: center; justify-content: center; color: #fff; }
.cell.free { background: #d1fae5; }
.cell.used { background: #3b82f6; font-family: ui-monospace, monospace; }

